#include <stdio.h>
#include <stdlib.h>

/* Elevator works on floors 0 .. 9 inclusive */
#define MIN_FLOOR 0
#define MAX_FLOOR 9

int main(int argc, char *argv[])
{
    int current = 0;               /* current floor, starts at 0 */
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target = strtol(argv[i], &endptr, 10);
        /* Invalid if non‑numeric or out of range */
        if (*endptr != '\0' || target < MIN_FLOOR || target > MAX_FLOOR) {
            puts("INVALID_FLOOR");
            continue;
        }
        while (current != (int)target) {
            if (current < (int)target) {
                printf("MOVE_UP %d->%d\n", current, current + 1);
                ++current;
            } else {
                printf("MOVE_DOWN %d->%d\n", current, current - 1);
                --current;
            }
        }
        printf("ARRIVE %d\n", current);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current);
    return 0;
}
